export const DOSSIER_CATALOG=Object.freeze(entries.map(entry=>Object.freeze({...entry,focus:Object.freeze(entry.focus)})));
export const NAMED_DOSSIERS=DOSSIER_CATALOG.filter(entry=>entry.kind==='named');
export const PENDING_DOSSIERS=DOSSIER_CATALOG.filter(entry=>entry.kind==='pending');
export const dossierById=id=>DOSSIER_CATALOG.find(entry=>entry.id===id);
export const dossierByTitle=title=>DOSSIER_CATALOG.find(entry=>entry.title===title);
export const dossierUrl=entry=>entry?.kind==='named'?`/types/${entry.id}/`:entry?.kind==='pending'?'/types/undetermined/':'/types/';
export const LEGACY_TYPE_CODES=Object.freeze([...'DS'].flatMap(a=>[...'WC'].flatMap(b=>[...'NA'].flatMap(c=>[...'XP'].map(d=>a+b+c+d)))));
